  "settings.pairTitle": {
    en: "Link another device", de: "Weiteres Gerät koppeln",
    tr: "Başka cihaz bağla", es: "Vincular otro dispositivo",
    fr: "Lier un autre appareil", pt: "Vincular outro dispositivo",
    ru: "Привязать другое устройство", ar: "ربط جهاز آخر",
    zh: "关联其他设备", hi: "दूसरा डिवाइस लिंक करें",
  },
  "settings.pairDesc": {
    en: "Transfer your identity to a second device with a sealed key exchange — the server never sees your keys.",
    de: "Übertrage deine Identität via versiegeltem Schlüsselaustausch auf ein zweites Gerät — der Server sieht deine Schlüssel nie.",
    tr: "Kimliğini mühürlü bir anahtar değişimiyle ikinci bir cihaza aktar — sunucu anahtarlarını asla görmez.",
    es: "Transfiere tu identidad a un segundo dispositivo con un intercambio de claves sellado — el servidor nunca ve tus claves.",
    fr: "Transférez votre identité vers un second appareil via un échange de clés scellé — le serveur ne voit jamais vos clés.",
    pt: "Transfira sua identidade para um segundo dispositivo com uma troca de chaves selada — o servidor nunca vê suas chaves.",
    ru: "Перенесите свою личность на второе устройство через запечатанный обмен ключами — сервер никогда не видит ваши ключи.",
    ar: "انقل هويتك إلى جهاز ثانٍ عبر تبادل مفاتيح مختوم — لا يرى الخادم مفاتيحك أبدًا.",
    zh: "通过密封的密钥交换将你的身份转移到第二台设备——服务器永远看不到你的密钥。",
    hi: "सीलबंद कुंजी विनिमय के साथ अपनी पहचान दूसरे डिवाइस पर स्थानांतरित करें — सर्वर आपकी कुंजियाँ कभी नहीं देखता।",
  },
  "settings.pairBeta": {
    en: "Beta: the sealed key crypto is unit-tested, but the full two-device flow (history sync, multi-device delivery) still needs testing on two real devices. The pairing below works by copy-paste — the secret never touches the server.",
    de: "Beta: die versiegelte Schlüssel-Krypto ist unit-getestet, aber der vollständige Zwei-Geräte-Ablauf (Historien-Sync, Multi-Device-Zustellung) muss noch auf zwei echten Geräten getestet werden. Die Kopplung unten läuft per Copy-Paste — das Geheimnis berührt den Server nie.",
    tr: "Beta: mühürlü anahtar kriptosu birim testlerinden geçti, ancak tam iki cihazlı akış (geçmiş senkronu, çok cihazlı teslimat) iki gerçek cihazda test edilmeli. Aşağıdaki eşleştirme kopyala-yapıştır ile çalışır — sır sunucuya asla dokunmaz.",
    es: "Beta: la criptografía de clave sellada está probada por unidades, pero el flujo completo de dos dispositivos (sincronización del historial, entrega multidispositivo) aún debe probarse en dos dispositivos reales. El emparejamiento de abajo funciona por copiar y pegar — el secreto nunca toca el servidor.",
    fr: "Bêta : la crypto à clé scellée est testée unitairement, mais le flux complet à deux appareils (synchro de l'historique, livraison multi-appareils) doit encore être testé sur deux appareils réels. L'appairage ci-dessous fonctionne par copier-coller — le secret ne touche jamais le serveur.",
    pt: "Beta: a criptografia de chave selada tem testes de unidade, mas o fluxo completo de dois dispositivos (sincronização do histórico, entrega multidispositivo) ainda precisa ser testado em dois dispositivos reais. O emparelhamento abaixo funciona por copiar e colar — o segredo nunca toca o servidor.",
    ru: "Бета: криптография запечатанного ключа покрыта модульными тестами, но полный сценарий с двумя устройствами (синхронизация истории, доставка на несколько устройств) ещё нужно проверить на двух реальных устройствах. Сопряжение ниже работает копированием-вставкой — секрет никогда не попадает на сервер.",
    ar: "تجريبي: تشفير المفتاح المختوم مُختبَر وحدويًا، لكن المسار الكامل لجهازين (مزامنة السجلّ، التسليم متعدد الأجهزة) لا يزال بحاجة إلى اختبار على جهازين حقيقيين. الإقران أدناه يعمل بالنسخ واللصق — السر لا يمسّ الخادم أبدًا.",
    zh: "测试版：密封密钥加密已通过单元测试，但完整的双设备流程（历史同步、多设备投递）仍需在两台真实设备上测试。下面的配对通过复制粘贴完成——密钥永远不会接触服务器。",
    hi: "बीटा: सीलबंद कुंजी क्रिप्टो यूनिट-परीक्षित है, लेकिन पूर्ण दो-डिवाइस प्रवाह (इतिहास सिंक, मल्टी-डिवाइस वितरण) को अभी भी दो वास्तविक डिवाइसों पर परीक्षण की आवश्यकता है। नीचे की पेयरिंग कॉपी-पेस्ट से काम करती है — रहस्य कभी सर्वर को नहीं छूता।",
  },
