    tr: "Şu anda bağlı oturumlar. Sunucu yalnızca opak, rastgele bir cihaz kimliğini ve bağlanma zamanını bilir — IP veya cihaz adı yok. Yalnızca o cihazdan çıkmak için birini iptal et.",
    es: "Sesiones conectadas actualmente. El servidor solo conoce un id de dispositivo opaco y aleatorio y la hora de conexión — sin IP ni nombre de dispositivo. Revoca una para cerrar sesión solo en ese dispositivo.",
    fr: "Sessions actuellement connectées. Le serveur ne connaît qu'un identifiant d'appareil opaque et aléatoire et l'heure de connexion — pas d'IP, pas de nom d'appareil. Révoquez-en une pour déconnecter uniquement cet appareil.",
    pt: "Sessões conectadas no momento. O servidor só conhece um id de dispositivo opaco e aleatório e a hora de conexão — sem IP, sem nome de dispositivo. Revogue uma para sair apenas daquele dispositivo.",
    ru: "Текущие подключённые сеансы. Сервер знает только непрозрачный случайный идентификатор устройства и время подключения — без IP и имени устройства. Отзовите один, чтобы выйти только на этом устройстве.",
    ar: "الجلسات المتصلة حاليًا. لا يعرف الخادم سوى معرّف جهاز عشوائي مبهم ووقت الاتصال — بدون IP أو اسم جهاز. ألغِ واحدة لتسجيل الخروج من ذلك الجهاز فقط.",
    zh: "当前已连接的会话。服务器只知道一个不透明的随机设备 id 和连接时间——没有 IP，没有设备名。撤销某个会话即可仅登出该设备。",
