    tr: "Her yerden çıkış yap: hesabının sunucudaki tüm oturum jetonlarını geçersiz kılar. Bir cihaz kaybolduysa veya bir jeton ele geçirildiyse kullan. Burada yeniden giriş yapman gerekir.",
