  "plan.title": {
    en: "Plan & subscription", de: "Plan & Abonnement", tr: "Plan ve abonelik",
    es: "Plan y suscripción", fr: "Forfait et abonnement", pt: "Plano e assinatura",
    ru: "План и подписка", ar: "الخطة والاشتراك", zh: "套餐与订阅",
    hi: "प्लान और सदस्यता",
  },
  "plan.intro": {
    en: "Umbra is private — the server sees no content. The Pro plan unlocks higher limits (more emojis, longer voice messages, larger groups). Payment runs through an external provider (Stripe); Umbra itself stores no card or billing data.",
    de: "Umbra ist privat — der Server sieht keine Inhalte. Pro-Plan schaltet höhere Limits frei (mehr Emojis, längere Sprachnachrichten, größere Gruppen). Bezahlung läuft über einen externen Anbieter (Stripe), Umbra selbst speichert keine Karten- oder Rechnungsdaten.",
    tr: "Umbra özeldir — sunucu içerik görmez. Pro plan daha yüksek limitler açar (daha çok emoji, daha uzun sesli mesaj, daha büyük grup). Ödeme harici sağlayıcıyla (Stripe) yapılır; Umbra kart veya fatura verisi saklamaz.",
    es: "Umbra es privado — el servidor no ve contenido. El plan Pro desbloquea límites más altos (más emojis, mensajes de voz más largos, grupos más grandes). El pago se realiza mediante un proveedor externo (Stripe); Umbra no almacena datos de tarjeta ni facturación.",
    fr: "Umbra est privé — le serveur ne voit aucun contenu. Le forfait Pro débloque des limites plus élevées (plus d'emojis, messages vocaux plus longs, groupes plus grands). Le paiement passe par un prestataire externe (Stripe) ; Umbra ne stocke aucune donnée de carte ou de facturation.",
    pt: "O Umbra é privado — o servidor não vê conteúdo. O plano Pro libera limites maiores (mais emojis, mensagens de voz mais longas, grupos maiores). O pagamento é feito por um provedor externo (Stripe); o Umbra não armazena dados de cartão ou cobrança.",
    ru: "Umbra приватен — сервер не видит содержимое. План Pro открывает более высокие лимиты (больше эмодзи, длиннее голосовые, крупнее группы). Оплата идёт через внешнего провайдера (Stripe); Umbra не хранит данные карт и счетов.",
    ar: "Umbra خاص — الخادم لا يرى المحتوى. خطة Pro تفتح حدوداً أعلى (رموز أكثر، رسائل صوتية أطول، مجموعات أكبر). الدفع عبر مزوّد خارجي (Stripe)؛ Umbra لا يخزّن بيانات البطاقة أو الفواتير.",
    zh: "Umbra 注重隐私——服务器看不到内容。Pro 套餐解锁更高限额（更多表情、更长语音、更大群组）。付款通过外部提供商（Stripe）处理；Umbra 本身不存储卡或账单数据。",
    hi: "Umbra निजी है — सर्वर सामग्री नहीं देखता। Pro प्लान उच्च सीमाएँ खोलता है (अधिक इमोजी, लंबे वॉइस संदेश, बड़े समूह)। भुगतान बाहरी प्रदाता (Stripe) के माध्यम से होता है; Umbra स्वयं कार्ड या बिलिंग डेटा संग्रहीत नहीं करता।",
  },
