    pt: "O servidor não vê o conteúdo das mensagens nem os remetentes de DM. Os frames de grupo contêm apenas texto cifrado. Sem histórico de mensagens no servidor (backend de demonstração apenas em RAM).",
    ru: "Сервер не видит содержимое сообщений и отправителей личных сообщений. Групповые кадры содержат только шифртекст. На сервере нет истории сообщений (демо-бэкенд только в ОЗУ).",
