  "safety.howBody": {
    en: "The safety number is a deterministic function of both identity public keys via BLAKE2b. Every device pair shares the same number.",
    de: "Die Sicherheitsnummer ist eine deterministische Funktion beider Identity-Public-Keys mit BLAKE2b. Jedes Gerätepaar hat dieselbe Nummer.",
    tr: "Güvenlik numarası, her iki kimlik açık anahtarının BLAKE2b ile deterministik bir fonksiyonudur. Her cihaz çifti aynı numarayı paylaşır.",
    es: "El número de seguridad es una función determinista de ambas claves públicas de identidad mediante BLAKE2b. Cada par de dispositivos comparte el mismo número.",
    fr: "Le numéro de sécurité est une fonction déterministe des deux clés publiques d'identité via BLAKE2b. Chaque paire d'appareils partage le même numéro.",
    pt: "O número de segurança é uma função determinística de ambas as chaves públicas de identidade via BLAKE2b. Cada par de dispositivos compartilha o mesmo número.",
    ru: "Код безопасности — детерминированная функция обоих открытых ключей личности через BLAKE2b. Каждая пара устройств имеет одинаковый код.",
    ar: "رقم الأمان دالة حتمية لكلا مفتاحي الهوية العامين عبر BLAKE2b. كل زوج من الأجهزة يشترك في الرقم نفسه.",
    zh: "安全码是两个身份公钥经 BLAKE2b 得出的确定性函数。每对设备共享相同的号码。",
    hi: "सुरक्षा नंबर BLAKE2b के माध्यम से दोनों पहचान सार्वजनिक कुंजियों का एक नियतात्मक फलन है। प्रत्येक डिवाइस जोड़ी का नंबर समान होता है।",
  },
